raw:
{
  "scores": {
    "开钩": {
      "score": 9,
      "failures": [
        "“吉时到——以女配之骨祭双璧！”主祭人阴沉的嗓音回荡殿顶，带着蜂鸣式回声。——前一句强势，后半句“蜂鸣式回声”属抽象比喻，缺乏具体可感画面，略显空泛。",
        "【滴——恋爱脑清零系统上线…】——系统窗直接丢大段提示文字，瞬间打断现场生死张力，略显信息轰炸。"
      ],
      "success": "“火光猩红，映得石顶像被烙铁灼出裂纹。”——两秒出视觉+疼痛感+高危场景，读者快速进入危机。",
      "suggestion": "系统信息精简到一句关键信息，其余用动作、心跳等动态衔接，避免掐断紧张气氛。"
    },
    "节奏": {
      "score": 8,
      "failures": [
        "宏观：整座大殿法光乱窜；微物：柱身金漆被电弧灼出芝麻大气泡… ——同类描写连用，事件暂停，易造成节奏堆滞。",
        "方脸杂役粗暴翻箱，“找到了。”——之后出现七行环境描写再接一句对话，来回切镜头频繁，略削流畅度。"
      ],
      "success": "她拔高嗓音…→锁链收紧→反借力弹射→斩柱——一个“挑衅—反制—小胜”闭环在200字内完成，爽点紧凑。",
      "suggestion": "每次动作高潮后给角色2-3句情绪或者信息反思即可，避免连环“宏观/微物”停顿式插入。"
    },
    "角色": {
      "score": 8,
      "failures": [
        "副祭…袖口不停敲自己指节，眸中贪婪闪动——短暂露面塞满小动作，标签化‘贪’却未与后文行为呼应，显得堆料。",
        "沈孤帧初登场连用三句‘冷香、雪色、冰’意象，略趋同，人物冷感有余、立体度不足。"
      ],
      "success": "女主把祭坛当“动画分镜”拆解，现代职业口癖‘写甘特图’反差强，性格一下子立住。",
      "suggestion": "给反派/男主留一个与主线冲突的私欲或软肋，用后续行动展现，而非一次性堆特写小习惯。"
    },
    "画面": {
      "score": 8,
      "failures": [
        "“墙面法阵浮现出男女主剪影：一白一蓝”——色块抽象，缺乏材质、光影细节，画面感停在概念层。",
        "夜半井边段落：‘月亮高而薄，像一枚铺开的银片’紧跟‘银片’后再写‘银片’材质，比喻复用，显冗余。"
      ],
      "success": "“电弧灼出芝麻大气泡，砰碎，溅落黑渣”——微距细节+动态声画，读者能即时想象。", 
      "suggestion": "原则：大场景1-2句概括后给1个触感或嗅觉增强层次，避免全篇皆高饱和视觉堆砌。"
    },
    "对话": {
      "score": 7,
      "failures": [
        "“老板又扣绩效。”——现代梗插在生死场景，喜感虽在却削弱当时致命后果，情绪错位。",
        "“杂役还想辞职？你当这是凡人作坊？”——对手台词套路化‘你当××’，缺乏角色本身语气特征。"
      ],
      "success": "阮澄：“作坊也规避劳资纠纷。”——用打工人逻辑杠古风执事，反差笑点自然。",
      "suggestion": "给不同身份设置关键词：杂役多粗口+行话，仙尊简短含锋，系统干脆冷静数据流，台词节奏更分明。"
    },
    "悬念": {
      "score": 8,
      "failures": [
        "【宿主寿元-1天，剩余：89天23时59分】——具体数字过细，观感像提醒闹钟，降解紧迫感。",
        "多次提示‘召形失败，原料全损’但未立即说明后果或解决方案，悬念堆累而短期不兑现。"
      ],
      "success": "井边遭遇沈孤帧，合作/抓捕未定，双方动机对立留巨大想象空间，强钩后文。",
      "suggestion": "倒计时用模糊渐减法+关键节点红字提示；失败悬念最好在同章给出一点补偿性转折。"
    },
    "情张": {
      "score": 7,
      "failures": [
        "反复出现‘前世熬夜剪片赶DDL’情绪闪回，情感共鸣点单一，次数多显得公式化。",
        "与沈孤帧互动多靠物理距离+香味提示，情愫层级未上升，读者难产生CP嗑点。"
      ],
      "success": "祭台生死、寿元连削，女主仍嘴硬操作，生存渴望与职业倔强并行，带出爽虐混合张力。",
      "suggestion": "尝试让男主在关键刹那提供低调援手或暴露自损代价，增加情绪深度与暧昧火花。"
    },
    "设定": {
      "score": 8,
      "failures": [
        "‘恋爱脑清零系统’+‘寿元-X年’+‘机缘光环+300’等设定出现频，规则层级未梳理，读者易混淆优先级。",
        "绘灵、画卷、召形代价与宗门禁令关系描述较浅，缺乏权力生态链支撑。"
      ],
      "success": "用‘寿元换自由’硬成本束缚，直接驱动女主选择，设定与情节高度绑定。",
      "suggestion": "列一条“资源—代价—收益”三段式内规并让角色口头或行动中自然透露，维系系统简洁感。"
    },
    "章差": {
      "score": 8,
      "failures": [
        "第二、三章连续尝试召形失败，剧情目标相似，事件动机略显重复。",
        "多次出现仓库/废井等灰暗场景，色调连续偏冷，缺少色温对比。"
      ],
      "success": "首章祭坛高压→二章职场讼诉→三章夜探+男主相遇，场面功能迭代，确保阅读黏性。",
      "suggestion": "第三章可插入轻喜或外界节日暖色场面，制造色与事节奏反差。"
    },
    "外描": {
      "score": 7,
      "failures": [
        "“衣袍雪色…眉心细红痕…像薄冰破缝却凝而不散”——比喻接比喻，层叠化妆式描写，易疲劳。",
        "女主多次被写成‘纤细身形…单膝跪稳’，形象标签重复。",
      ],
      "success": "方脸杂役‘肩头一块墨斑像蜈蚣趴着’+‘扑腰带’动作，瞬间可视且加深粗鄙感。",
      "suggestion": "原则：首次亮相全景+独有特征1，后续用‘动态 + 1细节’补充，避免整体颜描复读。"
    }
  },
  "weighted_total": 7.9,
  "strengths": [
    "反差笑点：阮澄用“作坊劳资纠纷”怼执事，将现代职场语言嵌入修真生死局（第2章），形成高密度爽感。",
    "场景可视：‘电弧灼出芝麻大气泡，砰碎，溅落黑渣’（第1章）以声音、尺寸、动态三线并行，画面鲜活。"
  ],
  "top_issues": [
    {
      "problem": "过度堆叠宏观/微物分镜与紫色修辞，易拖慢打戏与情绪。",
      "prompt_fix": "规则：每处动作高潮后, 描写≤2句且避免连用相同修辞标签（宏观/微物/比喻）。",
      "rewrite_example": "原句：宏观：整座大殿法光乱窜；微物：柱身金漆被电弧灼出芝麻大气泡…\n改写：电弧闪过，法阵光线扭曲成蛇，柱身金漆噼啪崩裂。碎漆落地，烫出淡白烟丝。"
    },
    {
      "problem": "系统与设定信息一次性倾倒，读者接受负荷高。",
      "prompt_fix": "规则：系统提示≤20字核心+1行代价，其他信息改用角色独白或行动暗示。",
      "rewrite_example": "【系统】：改节点？寿元-5年。 \n阮澄嗤笑：剪片猝死都见过，五年买命值了。她握拳，胸口骤缩，像从生命里掰下一块时间。"
    },
    {
      "problem": "情感张力暂停在口舌交锋，缺少实质牵绊或伤害带来的心动/心疼节点。",
      "prompt_fix": "规则：每3000字内给予主CP一次‘身体/灵魂救援’或‘代价共享’情境。",
      "rewrite_example": "井口灵爆，碎石激射。沈孤帧袖中寒光一旋，将飞石尽数震碎，臂弯却被余波震裂流血。阮澄伸手按住他伤口，血滑过她指缝，“下次别挡，合作伙伴要一起活。”"
    }
  ]
}
